show databases;
use gram_panchayat;
show tables;
select * from citizen;
select * from certificate_type;
select* from certificate_application;
select * from panchayat_office;
update citizen c join panchayat_office po on c.village_name=po.village_name set c.address=po.village_name;
alter table certificate_application drop issued_date;
alter table certificate_application add column certificate_id int ,add column office_id int;
update certificate_application ca join certificate_type ct on ca.certificate_name=ct.certificate_name set ca.certificate_id=ct.certificate_type_id;
alter  table certificate_application drop certificate_name;
update certificate_application set office_id=1 where application_id=1001;
update certificate_application set office_id=2 where application_id=1002;
update certificate_application set office_id=3 where application_id=1003;
update certificate_application set office_id=4 where application_id=1004;
update certificate_application set office_id=5 where application_id=1005;
alter table certificate_application add constraint fn_key foreign key(citizen_id) references citizen (citizen_id);
describe certificate_application;
alter table certificate_application add constraint cert_id foreign key (certificate_id) references certificate_type(certificate_type_id);
alter table certificate_application add constraint off_id foreign key (office_id) references panchayat_office(office_id);
desc certificate_application;
