delete from citizen where citizen_id=101;
delete from certificate_type where certificate_type_id=1;
select * from citizen;
select * from certificate_application;
select full_name from citizen order by full_name asc;
select distinct village_name from panchayat_office;
select distinct certificate_name from certificate_type;
select distinct office_name from panchayat_office;
select * from certificate_application where application_status="under review";
select * from  panchayat_office where village_name="ramapuram";
select * from certificate_application where year( application_date)='2026';
select * from certificate_application order by application_date;
select * from certificate_type where certification_name ='income';
select * from certificate_type where certificate_name ='income' union  select * from certificate_type where certificate_name ='residance';
select * from certificate_application where month(application_date)=1 union select * from certificate_application where month(application_date)=2;
select full_name from citizen where village_name="ramapuram" union select full_name from citizen where village_name="lakshmipuram";
select full_name from citizen c join certificate_application ca  on c.citizen_id= ca.citizen_id join certificate_type ct on ca.certificate_id= ct.certificate_type_id where ct.certificate_name="property certificate";
select full_name from citizen where citizen_id in(select citizen_id from certificate_application ca join certificate_type ct on ca.certificate_id=ct.certificate_type_id where ct.certificate_name="property certificate") and citizen_id in(select citizen_id from certificate_application ca join certificate_type ct on ca.certificate_id=ct.certificate_type_id where ct.certificate_name="residence certificate");
select full_name from citizen where citizen_id in(select citizen_id from certificate_application where year(application_date)=2025)and citizen_id in(select citizen_id from certificate_application where year(application_date)=2026);
select full_name from citizen where citizen_id in(select citizen_id from certificate_application ca join certificate_type ct on ca.certificate_id=ct.certificate_type_id where ct.certificate_name="property certificate") and citizen_id not in(select citizen_id from certificate_application ca join certificate_type ct on ca.certificate_id=ct.certificate_type_id where ct.certificate_name="residence certificate");
select full_name from citizen where citizen_id not in(select citizen_id from certificate_application where year(application_date)=2025)and citizen_id in(select citizen_id from certificate_application where year(application_date)=2026);
